/**
 * The agent contract: what `lectio agents` prints and `/api/agents` serves.
 *
 * Generated by a pure function from the block and question registries and the instance's
 * limits, so it can't drift from the code. The runnable examples are data
 * (`tutorExamples`), rendered into the document and executed by an e2e test against a real
 * server — which is what stops the contract drifting from the API.
 */
import {APPROACHES, BLOCK_TYPES, PLANNED_BLOCK_TYPES} from '../blocks/index.ts';
import {CAPTION_MAX, SECONDS_PER_LABEL, SECONDS_TO_LOOK} from '../blocks/types.ts';
import {PLANNED_QUESTION_TYPES, QUESTION_TYPES} from '../questions/index.ts';
import {CAPTION_WORDS_MAX, FIGURE_ELEMENTS_MAX, MAX_COLORS, MIN_LABEL_PX, PHONE_FIGURE_WIDTH, ROW_NODES_MAX} from './figureLint.ts';
import {FIGURE_PALETTE} from './palette.ts';
import {AREAS, OUTCOMES} from './proposals.ts';
import {AIMS, DAILY_ROLES} from './types.ts';

export interface ContractOptions {
  version: string;
  limits: Record<string, number>;
}

/**
 * One runnable example. Placeholders in angle brackets (`<run>`, `<subject>`, `<today>`…)
 * are filled in by the reader — and by the test — from earlier results and the context.
 */
export interface Example {
  section: string;
  /** The command line, starting with `lectio`, shell-quoted. */
  line: string;
  /** Text piped to stdin, if any. */
  stdin?: string;
  /** A file the line names, and what it holds. */
  file?: {name: string; content: unknown};
  /** The exit code it should have when run as documented. */
  expect?: number;
  /** Who runs it, when not the tutor. */
  as?: string;
}

